  ('gs-satt-board-barishal-2024-mcq-004', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p7', 'লেন্সটির ক্ষেত্রে সঠিক উক্তিগুলি হলো- i. এটি উত্তল ii. এটি হ্রস্বদৃষ্টি ত্রুটি প্রতিকারে ব্যবহৃত হয় iii. এটি এক গুচ্ছ সমান্তরাল আলোকরশ্মিকে অপসারী করে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'gs-satt-board-barishal-2024-mcq', false, 'board-mcq', 'উদ্দীপক ছবি আকারে (ছাপায় লেখা নেই)', null, 'barishal', 2024, true),
  ('gs-satt-board-barishal-2024-mcq-005', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p8', 'প্রিতমের জীবনে এই সময়কে কী বলা হয়?', 'mcq', '{"ক":"শৈশবকাল","খ":"বাল্যকাল","গ":"বয়ঃসন্ধিকাল","ঘ":"যৌবনকাল"}'::jsonb, 'গ', 1, false, 'gs-satt-board-barishal-2024-mcq', false, 'board-mcq', null, 'প্রিতম ৭ম শ্রেণিতে পড়ে। এ সময় তার শারীরিক ও মানসিক পরিবর্তন হয়।', 'barishal', 2024, true),
  ('gs-satt-board-barishal-2024-mcq-006', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p8', 'এ সময় প্রিতমের কোন ধরনের শারীরিক পরিবর্তন হয়? i. দ্রুত দৈহিক বৃদ্ধি পায় ii. কন্ঠস্বরের পরিবর্তন হয় iii. শারীরিক গঠন সম্পূর্ণ হয় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'gs-satt-board-barishal-2024-mcq', false, 'board-mcq', null, 'প্রিতম ৭ম শ্রেণিতে পড়ে। এ সময় তার শারীরিক ও মানসিক পরিবর্তন হয়।', 'barishal', 2024, true),
  ('gs-satt-board-barishal-2024-mcq-007', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p8', '''A'' বাতিটি দৈনিক ৫ ঘন্টা জ্বালালে মাসে কত ইউনিট বিদ্যুৎ শক্তি ব্যয় হবে?', 'mcq', '{"ক":"0.5 ইউনিট","খ":"3 ইউনিট","গ":"15 ইউনিট","ঘ":"15.5 ইউনিট"}'::jsonb, 'গ', 1, false, 'gs-satt-board-barishal-2024-mcq', false, 'board-mcq', 'উদ্দীপক ছবি আকারে (ছাপায় লেখা নেই)', null, 'barishal', 2024, true),
  ('gs-satt-board-barishal-2024-mcq-008', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p8', 'উপরোক্ত সার্কিটে i B ও C পুরাপুরি ভোল্টেজ পাবে না ii. A বন্ধ হলে C জ্বলবে iii. C বন্ধ হলে Aও বন্ধ হয়ে যাবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-barishal-2024-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই | উদ্দীপক ছবি আকারে (ছাপায় লেখা নেই)', null, 'barishal', 2024, true),
