  ('gs-satt-board-chattogram-2017-mcq-027', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p144', 'উদ্ভিদের যে অংশে ঐ বিশেষ প্রযুক্তি ব্যবহৃত হয়, তা হলো- i. কাণ্ডের পর্ব ও পর্বমধ্য ii. পাতা ও মূলাংশ iii. পার্শ্বমুকুল ও ভ্রূণ নিচের কোনটি সঠিক', 'mcq', '{"ক":"i","খ":"ii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'gs-satt-board-chattogram-2017-mcq', false, 'board-mcq', null, 'নিপা কৃষিবিদ মামার সঙ্গে তার গবেষণা কেন্দ্রে গিয়ে সেখানে একটি কাচের ঘরে কিছু উদ্ভিদ আর বিলুপ্তপ্রায় কয়েকটি চারা দেখতে পেলো। মামা বললেন এখানে বিশেষ প্রযুক্তি ব্যবহার করে গাছগুলোর বংশ টিকিয়ে রাখা হয়।', 'chattogram', 2017, true),
  ('gs-satt-board-chattogram-2017-mcq-028', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p145', 'উদ্দীপকে কোন বিশেষ প্রযুক্তির কথা বলা হয়েছে?', 'mcq', '{"ক":"গুটিকলম","খ":"শাখা কলম","গ":"টিস্যু কালচার","ঘ":"DNA পরিবর্তন"}'::jsonb, 'গ', 1, false, 'gs-satt-board-chattogram-2017-mcq', false, 'board-mcq', null, 'নিপা কৃষিবিদ মামার সঙ্গে তার গবেষণা কেন্দ্রে গিয়ে সেখানে একটি কাচের ঘরে কিছু উদ্ভিদ আর বিলুপ্তপ্রায় কয়েকটি চারা দেখতে পেলো। মামা বললেন এখানে বিশেষ প্রযুক্তি ব্যবহার করে গাছগুলোর বংশ টিকিয়ে রাখা হয়।', 'chattogram', 2017, true),
  ('gs-satt-board-chattogram-2017-mcq-029', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p145', 'রহমান সাহেবকে দৃষ্টির এই ত্রুটি দূর করতে হলে ব্যবহার করতে হবে-', 'mcq', '{"ক":"উত্তল লেন্সের চশমা","খ":"দ্বি উত্তল লেন্সের চশমা","গ":"অবতল লেন্সের চশমা","ঘ":"দ্বি অবতল লেন্সের চশমা"}'::jsonb, 'গ', 1, false, 'gs-satt-board-chattogram-2017-mcq', false, 'board-mcq', 'ছাপায় ''ভালই'' লেখা (অন্য সেটে একই বাক্যে ''ভালোই'' ছাপা হয়েছে); হুবহু রাখা হয়েছে', 'রহমান সাহেব কাছের বস্তু ভালই দেখতে পান কিন্তু দূরের বস্তু পরিষ্কার দেখতে পান না।', 'chattogram', 2017, true),
