  ('gs-satt-board-chattogram-2020-mcq-021', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p54', 'সামুদ্রিক প্রবালের জীবনযাপনের জন্য উপযোগী তাপমাত্রা কত?', 'mcq', '{"ক":"১৫°C - ২১°C","খ":"২২°C - ২৮°C","গ":"২৯°C - ৩৪°C","ঘ":"৩১°C - ৩৬°C"}'::jsonb, 'খ', 1, false, 'gs-satt-board-chattogram-2020-mcq', false, 'board-mcq', null, null, 'chattogram', 2020, true),
  ('gs-satt-board-chattogram-2020-mcq-022', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p54', 'তেজস্ক্রিয় আইসোটোপ ব্যবহার করা হয়— i. রোগ নির্ণয় করার জন্য ii. রোগ নিরাময়ের জন্য iii. অঙ্গ-প্রত্যঙ্গের কর্ম পদ্ধতি বের করার জন্য নিচের কোনটি সঠিক', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'gs-satt-board-chattogram-2020-mcq', false, 'board-mcq', null, null, 'chattogram', 2020, true),
