  ('gs-satt-board-chattogram-2023-mcq-024', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p119', 'প্রচন্ড শীত নিবারণ করার জন্য বাজার থেকে একটি পোশাক কেনা হল। এটি বিশেষ এক ধরনের দ্বারা তৈরি। এর মাঝে ফাঁকা বা আটকে থাকে। পোশাকটির বৈশিষ্ট্য হলো— i.তাপ কুপরিবাহী ii.নমনীয়তা iii.রং নষ্ট হয় না', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i,ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-chattogram-2023-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই; প্রশ্নের বাক্য ছাপায় অসম্পূর্ণ (''এটি বিশেষ এক ধরনের দ্বারা তৈরি। এর মাঝে ফাঁকা বা আটকে থাকে।''); হুবহু রাখা হয়েছে', null, 'chattogram', 2023, true),
  ('gs-satt-board-chattogram-2023-mcq-025', 'class9-10-general-science-bn-guide', 'satt-gs-board-2017-2024.pdf p119', 'পোশাকটির ক্ষতি হবে না নিচের কোনটি দিয়ে?', 'mcq', '{"ক":"লঘু এসিড","খ":"তীব্র এসিড","গ":"ছত্রাক","ঘ":"মথ পোকা"}'::jsonb, null, 1, false, 'gs-satt-board-chattogram-2023-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই; প্রশ্নের বাক্য ছাপায় অসম্পূর্ণ (''এটি বিশেষ এক ধরনের দ্বারা তৈরি। এর মাঝে ফাঁকা বা আটকে থাকে।''); হুবহু রাখা হয়েছে', 'প্রচন্ড শীত নিবারণ করার জন্য বাজার থেকে একটি পোশাক কেনা হল। এটি বিশেষ এক ধরনের দ্বারা তৈরি। এর মাঝে ফাঁকা বা আটকে থাকে। পোশাকটির বৈশিষ্ট্য হলো— i.তাপ কুপরিবাহী ii.নমনীয়তা iii.রং নষ্ট হয় না', 'chattogram', 2023, true),
