  ('gs-satt-board-chattogram-2025-mcq-001', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p15', 'কত তম ক্রোমোজোমের নন-ডিসজাংশনের ফলে তাজুর স্ত্রীর উক্ত সমস্যা হয়েছে?', 'mcq', '{"ক":"২০","খ":"২১","গ":"২২","ঘ":"২৩"}'::jsonb, null, 1, false, 'gs-satt-board-chattogram-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই | উদ্দীপক সিলেট ২০২৫-এর শেষ পৃষ্ঠায় ছাপা', 'তাজুর রক্তে লোহিত কণিকাগুলোর আকৃতি কিছুটা কাস্তের মতো। তার স্ত্রীর হাতগুলো তুলনামূলকভাবে ছোট। তার চাচার মস্তিষ্ক ঠিক মতো কাজ করে না।', 'chattogram', 2025, true),
  ('gs-satt-board-chattogram-2025-mcq-002', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p15', 'তাজু ও তার চাচার উক্ত অবস্থার কারণে যে সমস্যাগুলো হতে পারে- i. শরীরে রক্ত শূন্যতা দেখা দিবে ii. মানসিক ভারসাম্য নষ্ট হবে iii. বন্ধ্যাত্বতা দেখা দিবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-chattogram-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই | উদ্দীপক সিলেট ২০২৫-এর শেষ পৃষ্ঠায় ছাপা', 'তাজুর রক্তে লোহিত কণিকাগুলোর আকৃতি কিছুটা কাস্তের মতো। তার স্ত্রীর হাতগুলো তুলনামূলকভাবে ছোট। তার চাচার মস্তিষ্ক ঠিক মতো কাজ করে না।', 'chattogram', 2025, true),
  ('gs-satt-board-chattogram-2025-mcq-003', 'class9-10-general-science-bn-guide', 'satt-gs-board-2025.pdf p15', 'বর্তনীটির ক্ষেত্রে- i. এটি সমান্তরাল বর্তনী ii. প্রতিটি বাতি সমান ভোল্টেজ পাবে iii. একটি বাতি নষ্ট হলে অন্য বাতিগুলো জ্বলবে না নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i ii ও iii"}'::jsonb, null, 1, false, 'gs-satt-board-chattogram-2025-mcq', false, 'board-mcq', 'ছাপায় উত্তর-কি নেই | উদ্দীপক ছবি আকারে (ছাপায় লেখা নেই)', null, 'chattogram', 2025, true),
